            Err(BivvyError::ConfigValidationError {
                message: "test".into(),
            })
        }
        assert!(returns_error().is_err());
    }

    #[test]
    fn cache_error_displays_message() {
        let err = BivvyError::CacheError {
            message: "directory not writable".into(),
        };
        assert!(err.to_string().contains("directory not writable"));
    }

