            url: "https://example.com/config.yml".into(),
            message: "HTTP 404".into(),
        };
        let msg = err.to_string();
        assert!(msg.contains("https://example.com/config.yml"));
        assert!(msg.contains("HTTP 404"));
    }

    #[test]
    fn extends_error_displays_message() {
        let err = BivvyError::ExtendsError {
            message: "depth exceeds maximum".into(),
        };
        assert!(err.to_string().contains("depth exceeds maximum"));
    }

    #[test]
    fn session_error_displays_message() {
        let err = BivvyError::SessionError {
            message: "failed to write session".into(),
        };
        assert!(err.to_string().contains("failed to write session"));
    }

    #[test]
    fn feedback_error_displays_message() {
        let err = BivvyError::FeedbackError {
            message: "failed to open store".into(),
        };
        assert!(err.to_string().contains("failed to open store"));
    }

    #[test]
    fn update_error_displays_message() {
        let err = BivvyError::UpdateError {
            message: "failed to stage binary".into(),
        };
        assert!(err.to_string().contains("failed to stage binary"));
    }

    #[test]
    fn git_error_displays_message() {
        let err = BivvyError::GitError {
            message: "clone failed".into(),
        };
        assert!(err.to_string().contains("clone failed"));
    }

    #[test]
    fn serialization_error_displays_message() {
        let err = BivvyError::SerializationError {
            message: "invalid JSON".into(),
        };
        assert!(err.to_string().contains("invalid JSON"));
    }

    #[test]
    fn serde_json_error_converts_to_serialization_error() {
        let json_err = serde_json::from_str::<serde_json::Value>("not json").unwrap_err();
        let err: BivvyError = json_err.into();
        assert!(matches!(err, BivvyError::SerializationError { .. }));
    }

    #[test]
    fn serde_yaml_error_converts_to_serialization_error() {
        let yaml_err = serde_yaml::from_str::<serde_yaml::Value>("a: [invalid").unwrap_err();
        let err: BivvyError = yaml_err.into();
        assert!(matches!(err, BivvyError::SerializationError { .. }));
    }

    #[test]
    fn parse_int_error_converts_to_config_validation_error() {
        let parse_err = "not_a_number".parse::<i64>().unwrap_err();
        let err: BivvyError = parse_err.into();
        assert!(matches!(err, BivvyError::ConfigValidationError { .. }));
    }

    #[test]
    fn other_variant_removed() {
        // Verify that BivvyError no longer has an Other variant by testing
        // that all variants are accounted for in an exhaustive match
        let err = BivvyError::CacheError {
            message: "test".into(),
        };
        match err {
            BivvyError::ConfigNotFound { .. }
            | BivvyError::ConfigParseError { .. }
            | BivvyError::ConfigValidationError { .. }
            | BivvyError::UnknownTemplate { .. }
            | BivvyError::CircularDependency { .. }
            | BivvyError::StepExecutionError { .. }
            | BivvyError::CommandFailed { .. }
            | BivvyError::RequirementMissing { .. }
            | BivvyError::RequirementCheckFailed { .. }
            | BivvyError::UntrustedUrl { .. }
            | BivvyError::ShellError { .. }
            | BivvyError::Io(_)
            | BivvyError::CacheError { .. }
            | BivvyError::NetworkError { .. }
            | BivvyError::ExtendsError { .. }
            | BivvyError::SessionError { .. }
            | BivvyError::FeedbackError { .. }
            | BivvyError::UpdateError { .. }
            | BivvyError::GitError { .. }
            | BivvyError::SerializationError { .. } => {}
        }
    }
}

