    #[error("Shell error: {message}")]
    ShellError { message: String },

    /// IO error wrapper.
    #[error("IO error: {0}")]
    Io(#[from] std::io::Error),

    /// Cache subsystem error.
    #[error("Cache error: {message}")]
    CacheError { message: String },

    /// Network request failed.
    #[error("Network error for {url}: {message}")]
    NetworkError { url: String, message: String },

    /// Config extension resolution failed.
    #[error("Extends error: {message}")]
    ExtendsError { message: String },

    /// Session subsystem error.
    #[error("Session error: {message}")]
    SessionError { message: String },

    /// Feedback subsystem error.
    #[error("Feedback error: {message}")]
    FeedbackError { message: String },

    /// Update subsystem error.
    #[error("Update error: {message}")]
    UpdateError { message: String },

    /// Git operation failed.
