    fn from(err: serde_yaml::Error) -> Self {
        BivvyError::SerializationError {
            message: err.to_string(),
        }
    }
}

impl From<std::num::ParseIntError> for BivvyError {
    fn from(err: std::num::ParseIntError) -> Self {
