    #[test]
    fn other_variant_removed() {
        // Verify that BivvyError no longer has an Other variant by testing
        // that all variants are accounted for in an exhaustive match
        let err = BivvyError::CacheError {
            message: "test".into(),
        };
        match err {
            BivvyError::ConfigNotFound { .. }
            | BivvyError::ConfigParseError { .. }
            | BivvyError::ConfigValidationError { .. }
            | BivvyError::UnknownTemplate { .. }
            | BivvyError::CircularDependency { .. }
            | BivvyError::StepExecutionError { .. }
            | BivvyError::CommandFailed { .. }
            | BivvyError::RequirementMissing { .. }
            | BivvyError::RequirementCheckFailed { .. }
            | BivvyError::UntrustedUrl { .. }
            | BivvyError::ShellError { .. }
            | BivvyError::Io(_)
            | BivvyError::CacheError { .. }
            | BivvyError::NetworkError { .. }
            | BivvyError::ExtendsError { .. }
            | BivvyError::SessionError { .. }
            | BivvyError::FeedbackError { .. }
            | BivvyError::UpdateError { .. }
            | BivvyError::GitError { .. }
            | BivvyError::SerializationError { .. } => {}
        }
    }
